import React, { useState, useRef, useEffect } from 'react';
import {
  MessageCircle, Send, Paperclip, Smile, Mic, X,
  Search, Filter, MoreVertical, Phone, Video, Star,
  Check, CheckCheck, Clock, User, Shield, Pin,
  Image, File, Download, Trash2, Copy, Eye,
  ChevronRight, VolumeX, Maximize2, Minimize2,
  ArrowLeft, Calendar, Clock as ClockIcon, Hash
} from 'lucide-react';

const Messages = () => {
  const [activeChat, setActiveChat] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [inputMessage, setInputMessage] = useState('');
  const [notifications, setNotifications] = useState(3);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const messagesEndRef = useRef(null);
  const fileInputRef = useRef(null);

  // Données des conversations
  const [conversations, setConversations] = useState([
    {
      id: 1,
      name: 'Sarah Johnson',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah',
      status: 'online',
      lastMessage: 'Je vous remercie pour votre aide !',
      time: '10:30',
      unread: true,
      pinned: true,
      messages: [
        { id: 1, text: 'Bonjour, j\'ai une question concernant la facturation', time: '09:15', sender: 'them', status: 'read' },
        { id: 2, text: 'Bonjour Sarah, je peux vous aider. Quel est le problème ?', time: '09:20', sender: 'me', status: 'read' },
        { id: 3, text: 'Je n\'arrive pas à télécharger ma facture du mois dernier', time: '09:22', sender: 'them', status: 'read' },
        { id: 4, text: 'Je vais vérifier cela immédiatement', time: '09:25', sender: 'me', status: 'read' },
        { id: 5, text: 'Je vous remercie pour votre aide !', time: '10:30', sender: 'them', status: 'read' },
      ]
    },
    {
      id: 2,
      name: 'Michael Chen',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Michael',
      status: 'offline',
      lastMessage: 'Le rapport est prêt pour révision',
      time: 'Hier',
      unread: false,
      pinned: true,
      messages: [
        { id: 1, text: 'Le rapport trimestriel est prêt', time: '16:45', sender: 'them', status: 'read' },
        { id: 2, text: 'Parfait, je vais le réviser aujourd\'hui', time: '16:50', sender: 'me', status: 'read' },
      ]
    },
    {
      id: 3,
      name: 'Emma Wilson',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Emma',
      status: 'online',
      lastMessage: 'Pouvez-vous relire le contrat ?',
      time: '09:45',
      unread: true,
      pinned: false,
      messages: [
        { id: 1, text: 'Bonjour, pouvez-vous relire le contrat ?', time: '09:45', sender: 'them', status: 'read' },
      ]
    },
    {
      id: 4,
      name: 'David Brown',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=David',
      status: 'away',
      lastMessage: 'Réunion demain à 14h',
      time: '2 jours',
      unread: false,
      pinned: false,
      messages: [
        { id: 1, text: 'Réunion confirmée pour demain à 14h', time: 'Hier', sender: 'them', status: 'read' },
        { id: 2, text: 'Merci pour l\'info, je serai présent', time: 'Hier', sender: 'me', status: 'read' },
      ]
    },
    {
      id: 5,
      name: 'Support Technique',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Support',
      status: 'online',
      lastMessage: 'Votre problème a été résolu',
      time: '1 semaine',
      unread: false,
      pinned: false,
      messages: [
        { id: 1, text: 'Votre ticket a été résolu', time: '1 semaine', sender: 'them', status: 'read' },
        { id: 2, text: 'Merci pour votre aide !', time: '1 semaine', sender: 'me', status: 'read' },
      ]
    }
  ]);

  // Messages de la conversation active
  const activeConversation = conversations.find(conv => conv.id === activeChat);

  // Filtrage des conversations
  const filteredConversations = conversations.filter(conv =>
    conv.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.lastMessage.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Auto-scroll
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (activeConversation) {
      setTimeout(() => {
        scrollToBottom();
      }, 100);
    }
  }, [activeConversation]);

  // Envoyer un message
  const handleSendMessage = () => {
    if (inputMessage.trim() && activeConversation) {
      const currentMessages = activeConversation.messages;
      const newMessage = {
        id: currentMessages.length + 1,
        text: inputMessage,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        sender: 'me',
        status: 'sent'
      };

      const updatedConversations = conversations.map(conv => {
        if (conv.id === activeChat) {
          return {
            ...conv,
            lastMessage: inputMessage,
            time: 'Maintenant',
            messages: [...conv.messages, newMessage]
          };
        }
        return conv;
      });

      setConversations(updatedConversations);
      setInputMessage('');

      // Réponse automatique après 1 seconde
      setTimeout(() => {
        setConversations(prevConversations => {
          return prevConversations.map(conv => {
            if (conv.id === activeChat) {
              const autoReply = {
                id: conv.messages.length + 1,
                text: "Merci pour votre message. Je vais y répondre dès que possible.",
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                sender: 'them',
                status: 'read'
              };
              return {
                ...conv,
                messages: [...conv.messages, autoReply]
              };
            }
            return conv;
          });
        });
      }, 1000);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  // Marquer comme lu
  const markAsRead = (conversationId) => {
    setConversations(prev => prev.map(conv => 
      conv.id === conversationId ? { ...conv, unread: false } : conv
    ));
  };

  // Toggle pin
  const togglePin = (conversationId) => {
    setConversations(prev => prev.map(conv => 
      conv.id === conversationId ? { ...conv, pinned: !conv.pinned } : conv
    ));
  };

  // Toggle fullscreen
  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  // Obtenir l'icône de statut
  const getStatusIcon = (status) => {
    switch (status) {
      case 'online': return <div className="h-2 w-2 rounded-full bg-green-500"></div>;
      case 'offline': return <div className="h-2 w-2 rounded-full bg-neutral-400"></div>;
      case 'away': return <div className="h-2 w-2 rounded-full bg-amber-500"></div>;
      default: return null;
    }
  };

  return (
    <div className={`bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 overflow-hidden ${isFullscreen ? 'fixed inset-4 z-50' : 'h-[600px]'}`}>
      <div className="flex h-full">

        {/* Sidebar des conversations */}
        <div className={`w-full md:w-80 lg:w-96 border-r border-neutral-200 dark:border-neutral-800 flex flex-col ${activeChat ? 'hidden md:flex' : 'flex'}`}>

          {/* Header Sidebar */}
          <div className="p-4 border-b border-neutral-200 dark:border-neutral-800">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-neutral-900 dark:text-white">Messages</h2>
              <div className="flex items-center space-x-2">
                {notifications > 0 && (
                  <span className="px-2 py-1 text-xs bg-red-500 text-white rounded-full">
                    {notifications}
                  </span>
                )}
                <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                  <MoreVertical className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                </button>
              </div>
            </div>

            {/* Barre de recherche */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-neutral-400" />
              <input
                type="text"
                placeholder="Rechercher des conversations..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500"
              />
            </div>

            {/* Filtres */}
            <div className="flex space-x-2 mt-3">
              <button className="px-3 py-1.5 text-sm bg-primary-500 text-white rounded-xl">
                Tous
              </button>
              <button className="px-3 py-1.5 text-sm bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-xl hover:bg-neutral-200 dark:hover:bg-neutral-700">
                Non lus
              </button>
              <button className="px-3 py-1.5 text-sm bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-xl hover:bg-neutral-200 dark:hover:bg-neutral-700">
                Épinglés
              </button>
            </div>
          </div>

          {/* Liste des conversations */}
          <div className="flex-1 overflow-y-auto">
            {filteredConversations.map((conversation) => (
              <div
                key={conversation.id}
                onClick={() => {
                  setActiveChat(conversation.id);
                  markAsRead(conversation.id);
                }}
                className={`p-4 border-b border-neutral-100 dark:border-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 cursor-pointer transition-colors ${activeChat === conversation.id ? 'bg-primary-50 dark:bg-primary-900/10' : ''} ${conversation.unread ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}
              >
                <div className="flex items-center space-x-3">
                  <div className="relative">
                    <img
                      src={conversation.avatar}
                      alt={conversation.name}
                      className="h-12 w-12 rounded-xl"
                    />
                    <div className="absolute -bottom-1 -right-1">
                      {getStatusIcon(conversation.status)}
                    </div>
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <h3 className="font-semibold text-neutral-900 dark:text-white truncate">
                        {conversation.name}
                      </h3>
                      <div className="flex items-center space-x-2">
                        {conversation.pinned && (
                          <Pin className="h-3 w-3 text-amber-500" />
                        )}
                        <span className="text-xs text-neutral-500 dark:text-neutral-500">
                          {conversation.time}
                        </span>
                      </div>
                    </div>

                    <p className="text-sm text-neutral-600 dark:text-neutral-400 truncate">
                      {conversation.lastMessage}
                    </p>

                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center space-x-2">
                        {conversation.unread && (
                          <div className="h-2 w-2 bg-primary-500 rounded-full animate-pulse"></div>
                        )}
                        <span className="text-xs text-neutral-500 dark:text-neutral-500">
                          {conversation.unread ? 'Nouveau message' : 'Vu'}
                        </span>
                      </div>
                      {conversation.unread && (
                        <span className="px-2 py-0.5 text-xs bg-primary-500 text-white rounded-full">
                          Nouveau
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Zone de chat principale */}
        <div className={`flex-1 flex flex-col ${activeChat ? 'flex' : 'hidden md:flex'}`}>

          {/* Header Chat */}
          {activeConversation ? (
            <>
              <div className="p-4 border-b border-neutral-200 dark:border-neutral-800 flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <button
                    onClick={() => setActiveChat(null)}
                    className="md:hidden p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl"
                  >
                    <ArrowLeft className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <div className="relative">
                    <img
                      src={activeConversation.avatar}
                      alt={activeConversation.name}
                      className="h-10 w-10 rounded-xl"
                    />
                    <div className="absolute -bottom-1 -right-1">
                      {getStatusIcon(activeConversation.status)}
                    </div>
                  </div>
                  <div>
                    <h3 className="font-bold text-neutral-900 dark:text-white">
                      {activeConversation.name}
                    </h3>
                    <div className="flex items-center space-x-2">
                      <span className="text-xs text-neutral-600 dark:text-neutral-400">
                        {activeConversation.status === 'online' ? 'En ligne' : 
                         activeConversation.status === 'offline' ? 'Hors ligne' : 'Absent'}
                      </span>
                      <span className="text-xs text-neutral-500 dark:text-neutral-500">•</span>
                      <span className="text-xs text-neutral-600 dark:text-neutral-400">
                        Dernière activité: {activeConversation.time}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Phone className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Video className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Star className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <button 
                    onClick={toggleFullscreen}
                    className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl"
                  >
                    {isFullscreen ? (
                      <Minimize2 className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                    ) : (
                      <Maximize2 className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                    )}
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <MoreVertical className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                </div>
              </div>

              {/* Zone des messages */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin scrollbar-thumb-neutral-300 dark:scrollbar-thumb-neutral-700">
                <div className="text-center">
                  <span className="px-3 py-1 text-xs bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 rounded-full">
                    Conversation commencée le 15 Nov 2024
                  </span>
                </div>

                {activeConversation.messages.map((message) => (
                  <div
                    key={message.id}
                    className={`flex ${message.sender === 'me' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className={`max-w-[70%] rounded-2xl p-4 ${message.sender === 'me'
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                      : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                    }`}>
                      <p className="text-sm">{message.text}</p>
                      <div className={`flex items-center justify-between mt-3 ${message.sender === 'me' ? 'text-white/80' : 'text-neutral-500'}`}>
                        <span className="text-xs">{message.time}</span>
                        {message.sender === 'me' && (
                          <div className="flex items-center space-x-1">
                            {message.status === 'sent' && <Check className="h-3 w-3" />}
                            {message.status === 'delivered' && <CheckCheck className="h-3 w-3" />}
                            {message.status === 'read' && <CheckCheck className="h-3 w-3 text-blue-400" />}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}

                <div ref={messagesEndRef} />
              </div>

              {/* Zone de saisie */}
              <div className="p-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="flex items-center space-x-3">
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Paperclip className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Image className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <Smile className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <div className="flex-1 relative">
                    <input
                      type="text"
                      value={inputMessage}
                      onChange={(e) => setInputMessage(e.target.value)}
                      onKeyPress={handleKeyPress}
                      placeholder="Écrivez votre message..."
                      className="w-full pl-4 pr-12 py-3 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500"
                    />
                    <button className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg">
                      <Mic className="h-4 w-4 text-neutral-600 dark:text-neutral-400" />
                    </button>
                  </div>
                  <button
                    onClick={handleSendMessage}
                    disabled={!inputMessage.trim()}
                    className={`p-3 rounded-xl transition-all duration-300 ${inputMessage.trim()
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25'
                      : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-400 cursor-not-allowed'
                    }`}
                  >
                    <Send className="h-5 w-5" />
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
              <div className="h-24 w-24 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center mb-6">
                <MessageCircle className="h-12 w-12 text-white" />
              </div>
              <h3 className="text-xl font-bold text-neutral-900 dark:text-white mb-2">
                Bienvenue dans Messages
              </h3>
              <p className="text-neutral-600 dark:text-neutral-400 text-center mb-6 max-w-md">
                Sélectionnez une conversation pour commencer à discuter ou créez une nouvelle conversation.
              </p>
              <button className="px-6 py-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300">
                Nouvelle conversation
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Messages;
